USER: Load settings from config.toml into a struct, with defaults for anything missing.

ASSISTANT: `#[serde(default)]` fills missing fields from `Default`, and a missing file yields all defaults.

```rust
// src/config.rs
use serde::Deserialize;
use std::{fs, path::Path};

#[derive(Debug, Deserialize)]
#[serde(default)]
pub struct Config {
    pub port: u16,
    pub log_level: String,
    pub workers: usize,
}

impl Default for Config {
    fn default() -> Self {
        Self { port: 8080, log_level: "info".into(), workers: 4 }
    }
}

pub fn load(path: &Path) -> anyhow::Result<Config> {
    if !path.exists() {
        return Ok(Config::default());
    }
    let raw = fs::read_to_string(path)?;
    Ok(toml::from_str(&raw)?)
}
```

